WITH UserStats AS (SELECT U.Id AS UserId, U.DisplayName, U.Reputation, COUNT(DISTINCT P.Id) AS TotalPosts, SUM(CASE WHEN P.PostTypeId = 1 THEN 1 ELSE 0 END) AS QuestionCount, SUM(CASE WHEN P.PostTypeId = 2 THEN 1 ELSE 0 END) AS AnswerCount, SUM(CASE WHEN P.PostTypeId IN (10, 12) THEN 1 ELSE 0 END) AS ClosedPosts, AVG(COALESCE(P.Score, 0)) AS AvgScore FROM Users AS U LEFT JOIN Posts AS P ON U.Id = P.OwnerUserId GROUP BY U.Id, U.DisplayName, U.Reputation), RecentActivity AS (SELECT PH.UserId, PH.CreationDate, ROW_NUMBER() OVER (PARTITION BY PH.UserId ORDER BY PH.CreationDate DESC NULLS FIRST) AS ActivityRank FROM PostHistory AS PH WHERE PH.CreationDate >= CAST('2024-10-01 12:34:56' AS Nullable(DateTime)) - INTERVAL '30' DAYS), UserBadges AS (SELECT B.UserId, COUNT(*) AS BadgeCount, GROUP_CONCAT(B.Name, ', ') AS BadgeNames FROM Badges AS B GROUP BY B.UserId) SELECT US.UserId, US.DisplayName, COALESCE(US.TotalPosts, 0) AS TotalPosts, COALESCE(US.QuestionCount, 0) AS QuestionCount, COALESCE(US.AnswerCount, 0) AS AnswerCount, COALESCE(US.ClosedPosts, 0) AS ClosedPosts, COALESCE(US.AvgScore, 0) AS AvgScore, CASE WHEN NOT (RA.ActivityRank IS NULL) THEN 'Active' ELSE 'Inactive' END AS ActivityStatus, UB.BadgeCount, UB.BadgeNames FROM UserStats AS US LEFT JOIN RecentActivity AS RA ON US.UserId = RA.UserId AND RA.ActivityRank = 1 LEFT JOIN UserBadges AS UB ON US.UserId = UB.UserId WHERE US.Reputation > 1000 ORDER BY US.Reputation DESC NULLS FIRST FETCH FIRST 100 ROWS ONLY